  "milestones": [
    {
      "task": "find a pig",
      "milestone_id": "find_pig",
      "description": "Uses position_near_with_facing because this is a 'find/locate' task — the player must navigate toward the fenced pig pen and visually observe the pigs. Target is the center of the pig pen at spawn-relative (5, 0, 5). With max_distance=8, the player (spawning ~7.07 blocks away) must walk a few steps toward the pen and face it. facing_tolerance=60 ensures the player is actually looking at the pigs, not just passing nearby. This rule type was chosen over position_inside_box because 'find' tasks model visual observation, not just proximity.",
      "rules": [
        {
          "type": "position_near_with_facing",
          "params": {
            "target": [5, 0, 5],
            "max_distance": 8,
            "facing_tolerance": 60,
            "coordinate_frame": "spawn_relative"
          }
        }
      ]
    },
    {
      "task": "find gold_ore",
      "milestone_id": "find_gold_ore",
      "description": "Uses position_near_with_facing because this is a 'find/locate' task — the player must enter or approach the cave interior and visually identify the gold_ore blocks on the walls. Target is the center of the gold_ore cluster at spawn-relative (11, 1, 13). With max_distance=10, the player must walk past the pig pen and into or near the cave entrance (~17 blocks from spawn, requiring ~7+ blocks of travel). facing_tolerance=60 ensures the player is looking toward the gold_ore deposits. This rule type correctly models 'player can see the target' without requiring them to stand on top of it.",
      "rules": [
        {
